 false;&quot;&#x27; : &#x27;&#x27;;                                let iconClass = link.icon ? `&lt;i class=&quot;$&#123;link.icon&#125; fa-fw&quot;&gt;&lt;/i&gt;` : &#x27;&#x27;;                                let linkText = __(i.toLowerCase()).toUpperCase();                                let dropdownIcon = hasSubmenus ? &#x27;&lt;i class=&quot;fa-solid fa-chevron-down fa-fw&quot;&gt;&lt;/i&gt;&#x27; : &#x27;&#x27;;                            %&gt;                            &lt;li class=&quot;navbar-item&quot;&gt;                                &lt;!-- Menu --&gt;                                &lt;a class=&quot;&lt;%= hasSubmenus ? &#x27;has-dropdown&#x27; : (isActive ? &#x27;active&#x27; : &#x27;&#x27;) %&gt;&quot;                                   href=&quot;&lt;%= linkHref %&gt;&quot;                                        &lt;%= onClickAction %&gt;&gt;                                    &lt;%- iconClass %&gt;                                    &lt;%= linkText %&gt;                                    &lt;%- dropdownIcon %&gt;                                &lt;/a&gt;                                &lt;!-- Submenu --&gt;                                &lt;% if (hasSubmenus) &#123; %&gt;                                    &lt;ul class=&quot;sub-menu&quot;&gt;                                        &lt;% for (var submenu in link.submenus) &#123; %&gt;                                            &lt;li&gt;                                                &lt;a href=&quot;&lt;%- url_for(link.submenus[submenu]) %&gt;&quot;&gt;                                                    &lt;%= __(submenu.toLowerCase()).toUpperCase() %&gt;                                                &lt;/a&gt;                                            &lt;/li&gt;                                        &lt;% &#125; %&gt;                                    &lt;/ul&gt;                                &lt;% &#125; %&gt;                            &lt;/li&gt;                    &lt;% &#125; &#125;