inkData.icon;                        let linkText = __(i.toLowerCase()).toUpperCase();                        let linkPath = hasSubmenus ? &#x27;#&#x27; : url_for(linkData.path);                        let drawerNavbarItemClass = hasSubmenus ? &#x27;drawer-navbar-item-sub&#x27; : &#x27;drawer-navbar-item&#x27;;                    %&gt;                    &lt;li class=&quot;&lt;%= drawerNavbarItemClass %&gt; text-base my-1.5 flex flex-col w-full&quot;&gt;                        &lt;% if (hasSubmenus) &#123;%&gt;                        &lt;div class=&quot;py-1.5 px-2 flex flex-row items-center justify-between gap-1 hover:!text-primary active:!text-primary cursor-pointer text-2xl font-semibold group border-b border-border-color hover:border-primary w-full &lt;%= isActive ? &#x27;active&#x27; : &#x27;&#x27; %&gt;&quot;                             navbar-data-toggle=&quot;submenu-&lt;%= i %&gt;&quot;                        &gt;                            &lt;span&gt;                                &lt;%= linkText %&gt;                            &lt;/span&gt;                            &lt;% if (iconClass) &#123; %&gt;                                &lt;i class=&quot;fa-solid fa-chevron-right fa-sm fa-fw transition-all&quot;&gt;&lt;/i&gt;                            &lt;% &#125; %&gt;                        &lt;/div&gt;                        &lt;% &#125; else &#123; %&gt;                        &lt;a class=&quot;py-1.5 px-2 flex flex-row items-center justify-between gap-1 hover:!text-primary active:!text-primary text-2xl font-semibold group border-b border-border-color hover:border-primary w-full &lt;%= isActive ? &#x27;active&#x27; : &#x27;&#x27; %&gt;&quot;                           href=&quot;&lt;%= linkPath %&gt;&quot;                        &gt;                            &lt;span&gt;                                &lt;%= linkText %&gt;                            &lt;/span&gt;                            &lt;% if (iconClass) &#123; %&gt;                                &lt;i class=&quot;&lt;%= iconClass %&gt; fa-sm fa-fw&quot;&gt;&lt;/i&gt;                            &lt;% &#125; %&gt;                        &lt;/a&gt;                        &lt;% &#125; %&gt;                        &lt;% if (hasSubmenus) &#123; %&gt;                            &lt;div class=&quot;flex-col items-start px-2 py-2 hidden&quot; data-target=&quot;submenu-&lt;%= i %&gt;&quot;&gt;                                &lt;% for (var submenu in linkData.submenus) &#123; %&gt;                                    &lt;div class=&quot;drawer-navbar-item text-base flex flex-col justify-center items-start hover:underline active:underline hover:underline-offset-1 rounded-3xl&quot;&gt;                                        &lt;a class=&quot; text-third-text-color text-xl&quot;                                           href=&quot;&lt;%- url_for(linkData.submenus[submenu]) %&gt;&quot;&gt;&lt;%= __(submenu.toLowerCase()).toUpperCase() %&gt;&lt;/a&gt;                                    &lt;/div&gt;                                &lt;% &#125; %&gt;                            &lt;/div&gt;                        &lt;% &#125; %&gt;                    &lt;/li&gt;            &lt;% &#125; &#125; %&gt;            &lt;%# Add sidebar links %&gt;            &lt;% if (theme.home.sidebar.links !== null &amp;&amp; theme.home.sidebar.show_on_mobile !== false) &#123;%&gt;                &lt;% for (let i in theme.home.sidebar.links) &#123; %&gt;                    &lt;% if (theme.navbar.links &amp;&amp; theme.navbar.links.hasOwnProperty(i)) &#123;                        continue;                    &#125; %&gt;                    &lt;li class=&quot;drawer-navbar-item text-base my-1.5 flex flex-col w-full&quot;&gt;                        &lt;a class=&quot;py-1.5 px-2 flex flex-row items-center justify-between gap-1 hover:!text-primary active:!text-primary text-2xl font-semibold group border-b border-border-color hover:border-primary w-full active&quot;                           href=&quot;&lt;%= url_for(theme.home.sidebar.links[i].path) %&gt;&quot;                        &gt;                            &lt;span&gt;&lt;%= __(i) %&gt;&lt;/span&gt;                            &lt;i class=&quot;&lt;%= theme.home.sidebar.links[i].icon %&gt; fa-sm fa-fw&quot;&gt;&lt;/i&gt;                        &lt;/a&gt;                    &lt;/li&gt;                &lt;% &#125; %&gt;            &lt;% &#125; %&gt;        &lt;/ul&gt;        &lt;%- partial(&quot;components/sidebar/statistics&quot;) %&gt;    &lt;/div&gt;    &lt;div class=&quot;window-mask&quot;&gt;&lt;/div&gt;&lt;/header&gt;




Detect external URLs (starts with http:&#x2F;&#x2F; or https:&#x2F;&#x2F;) and add target&#x3D;”_blank” and rel&#x3D;”noopener” to the anchor tags.
Apply this in both the desktop (PC) and mobile drawer rendering blocks you provided.

Suggested changes
1. Desktop menu items (the main navbar)In the section where you render the main list item, update the  tag to conditionally include the attributes when the URL is external.
Replace this part:
&lt;a class=&quot;&lt;%= hasSubmenus ? &#x27;has-dropdown&#x27; : (isActive ? &#x27;active&#x27; : &#x27;&#x27;) %&gt;&quot;   href=&quot;&lt;%= linkHref %&gt;&quot;        &lt;%= onClickAction %&gt;&gt;

With something like:
&lt;a class=&quot;&lt;%= hasSubmenus ? &#x27;has-dropdown&#x27; : (isActive ? &#x27;active&#x27; : &#x27;&#x27;) %&gt;&quot;   href=&quot;&lt;%= linkHref %&gt;&quot;   &lt;%= onClickAction %&gt;   &lt;%- (linkHref.startsWith(&#x27;http&#x27;)) ? &#x27; target=&quot;_blank&quot; rel=&quot;noopener&quot;&#x27; : &#x27;&#x27; %&gt;&gt;

Notes:

linkHref is already set to either ‘#’ or url_for(link.path). If external links come from link.path that’s an absolute URL, you may need to adjust the check to use the raw URL. Since linkHref is used, you can check the original URL:
If (typeof link.path &#x3D;&#x3D;&#x3D; ‘string’ &amp;&amp; (link.path.startsWith(‘http:&#x2F;&#x2F;‘) || link.path.startsWith(‘https:&#x2F;&#x2F;‘))) then add attributes.


If you prefer a simpler check, detect via link.path instead of linkHref:

&lt;% const isExternal = typeof link.path === &#x27;string&#x27; &amp;&amp; (link.path.startsWith(&#x27;http://&#x27;) || link.path.startsWith(&#x27;https://&#x27;)); %&gt;&lt;a class=&quot;&lt;%= hasSubmenus ? &#x27;has-dropdown&#x27; : (isActive ? &#x27;active&#x27; : &#x27;&#x27;) %&gt;&quot;   href=&quot;&lt;%= linkHref %&gt;&quot;   &lt;%= onClickAction %&gt;   &lt;%- isExternal ? &#x27; target=&quot;_blank&quot; rel=&quot;noopener&quot;&#x27; : &#x27;&#x27; %&gt;&gt;

2. Mobile drawer linksIn the mobile block where you render each drawer item:

For the non-submenu case, update the  tag similarly:

Original:
&lt;a class=&quot;py-1.5 px-2 flex flex-row items-center justify-between gap-1 hover:!text-primary active:!text-primary text-2xl font-semibold group border-b border-border-color hover:border-primary w-full &lt;%= isActive ? &#x27;active&#x27; : &#x27;&#x27; %&gt;&quot;   href=&quot;&lt;%= linkPath %&gt;&quot;&gt;

Replace with external-aware version:
&lt;%  const isExternal = typeof linkData.path === &#x27;string&#x27; &amp;&amp; (linkData.path.startsWith(&#x27;http://&#x27;) || linkData.path.startsWith(&#x27;https://&#x27;));  const linkHrefMobile = hasSubmenus ? &#x27;#&#x27; : url_for(linkData.path);%&gt;&lt;a class=&quot;py-1.5 px-2 flex flex-row items-center justify-between gap-1 hover:!text-primary active:!text-primary text-2xl font-semibold group border-b border-border-color hover:border-primary w-full &lt;%= isActive ? &#x27;active&#x27; : &#x27;&#x27; %&gt;&quot;   href=&quot;&lt;%= linkHrefMobile %&gt;&quot;   &lt;%- isExternal ? &#x27; target=&quot;_blank&quot; rel=&quot;noopener&quot;&#x27; : &#x27;&#x27; %&gt;&gt;

If you want to keep the logic centralized, you can declare isExternal at the top of the drawer item render, just like in the desktop block.
3. Optional: wrap a generic helper (less invasive)If you’d rather not edit every anchor, you can inject a tiny helper at the top of the template to mark external links and then reuse it:
&lt;%  function isExternalUrl(u) &#123;    return typeof u === &#x27;string&#x27; &amp;&amp; (u.startsWith(&#x27;http://&#x27;) || u.startsWith(&#x27;https://&#x27;));  &#125;%&gt;

Then use:
&lt;a ... &lt;%- isExternalUrl(linkPath) ? &#x27; target=&quot;_blank&quot; rel=&quot;noopener&quot;&#x27; : &#x27;&#x27; %&gt; &gt;

4. Verify for submenusIf a link has submenus, the desktop main anchor is used to toggle the dropdown (href may be ‘#’). External behavior usually applies to top-level links only. If you also want submenus’ top items external-aware, apply the same isExternal check to link.path (and ensure the href you render is external or internal as appropriate).

You need to modify two sections in your header template:1) Desktop navbar (PC section)Replace this section:
&lt;a class=&quot;&lt;%= hasSubmenus ? &#x27;has-dropdown&#x27; : (isActive ? &#x27;active&#x27; : &#x27;&#x27;) %&gt;&quot;   href=&quot;&lt;%= linkHref %&gt;&quot;        &lt;%= onClickAction %&gt;&gt;    &lt;%- iconClass %&gt;    &lt;%= linkText %&gt;    &lt;%- dropdownIcon %&gt;&lt;/a&gt;

With this:
&lt;%    let isExternal = linkHref.startsWith(&#x27;http://&#x27;) || linkHref.startsWith(&#x27;https://&#x27;);    let targetAttr = isExternal ? &#x27; target=&quot;_blank&quot; rel=&quot;noopener&quot;&#x27; : &#x27;&#x27;;%&gt;&lt;a class=&quot;&lt;%= hasSubmenus ? &#x27;has-dropdown&#x27; : (isActive ? &#x27;active&#x27; : &#x27;&#x27;) %&gt;&quot;   href=&quot;&lt;%= linkHref %&gt;&quot;        &lt;%= onClickAction %&gt;&lt;%= targetAttr %&gt;&gt;    &lt;%- iconClass %&gt;    &lt;%= linkText %&gt;    &lt;%- dropdownIcon %&gt;&lt;/a&gt;

2) Mobile drawer navbar (Mobile sheet section)For the main links in the drawer, replace:
&lt;a class=&quot;py-1.5 px-2 flex flex-row items-center justify-between gap-1 hover:!text-primary active:!text-primary text-2xl font-semibold group border-b border-border-color hover:border-primary w-full &lt;%= isActive ? &#x27;active&#x27; : &#x27;&#x27; %&gt;&quot;   href=&quot;&lt;%= linkPath %&gt;&quot;&gt;    &lt;span&gt;        &lt;%= linkText %&gt;    &lt;/span&gt;    &lt;% if (iconClass) &#123; %&gt;        &lt;i class=&quot;&lt;%= iconClass %&gt; fa-sm fa-fw&quot;&gt;&lt;/i&gt;    &lt;% &#125; %&gt;&lt;/a&gt;

With this:
&lt;%    let isExternalMobile = linkPath.startsWith(&#x27;http://&#x27;) || linkPath.startsWith(&#x27;https://&#x27;);    let targetAttrMobile = isExternalMobile ? &#x27; target=&quot;_blank&quot; rel=&quot;noopener&quot;&#x27; : &#x27;&#x27;;%&gt;&lt;a class=&quot;py-1.5 px-2 flex flex-row items-center justify-between gap-1 hover:!text-primary active:!text-primary text-2xl font-semibold group border-b border-border-color hover:border-primary w-full &lt;%= isActive ? &#x27;active&#x27; : &#x27;&#x27; %&gt;&quot;   href=&quot;&lt;%= linkPath %&gt;&quot;&lt;%= targetAttrMobile %&gt;&gt;    &lt;span&gt;        &lt;%= linkText %&gt;    &lt;/span&gt;    &lt;% if (iconClass) &#123; %&gt;        &lt;i class=&quot;&lt;%= iconClass %&gt; fa-sm fa-fw&quot;&gt;&lt;/i&gt;    &lt;% &#125; %&gt;&lt;/a&gt;

3) Also handle sidebar links (at the bottom)Replace:
&lt;a class=&quot;py-1.5 px-2 flex flex-row items-center justify-between gap-1 hover:!text-primary active:!text-primary text-2xl font-semibold group border-b border-border-color hover:border-primary w-full active&quot;   href=&quot;&lt;%= url_for(theme.home.sidebar.links[i].path) %&gt;&quot;&gt;    &lt;span&gt;&lt;%= __(i) %&gt;&lt;/span&gt;    &lt;i class=&quot;&lt;%= theme.home.sidebar.links[i].icon %&gt; fa-sm fa-fw&quot;&gt;&lt;/i&gt;&lt;/a&gt;

With this:
&lt;%    let sidebarPath = url_for(theme.home.sidebar.links[i].path);    let isExternalSidebar = sidebarPath.startsWith(&#x27;http://&#x27;) || sidebarPath.startsWith(&#x27;https://&#x27;);    let targetAttrSidebar = isExternalSidebar ? &#x27; target=&quot;_blank&quot; rel=&quot;noopener&quot;&#x27; : &#x27;&#x27;;%&gt;&lt;a class=&quot;py-1.5 px-2 flex flex-row items-center justify-between gap-1 hover:!text-primary active:!text-primary text-2xl font-semibold group border-b border-border-color hover:border-primary w-full active&quot;   href=&quot;&lt;%= sidebarPath %&gt;&quot;&lt;%= targetAttrSidebar %&gt;&gt;    &lt;span&gt;&lt;%= __(i) %&gt;&lt;/span&gt;    &lt;i class=&quot;&lt;%= theme.home.sidebar.links[i].icon %&gt; fa-sm fa-fw&quot;&gt;&lt;/i&gt;&lt;/a&gt;

4) Testinghexo clean &amp;&amp; hexo ghexo s

Then verify:

Internal links (relative paths) open in the same tab
External links (http&#x2F;https) open in a new tab with rel=&quot;noopener&quot;
Works on both desktop and mobile views

